    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Recipe home = new Recipe();
        home.accept(sc.next(), sc.nextInt(), sc.nextDouble());
        int target = sc.nextInt();
        Recipe party = home.scaled(target);
        home.display();
        party.display();
    }
}
